node -e "
const http = require('http');
const https = require('https');

console.log('Testing connectivity to http://localhost:47301/checkConnectivity?variant=3');

const req1 = http.request('http://localhost:47301/checkConnectivity?variant=3', (res) => {
  console.log('Status Code 1:', res.statusCode);
  let data = '';
  res.on('data', (chunk) => data += chunk);
  res.on('end', () => console.log('Response 1:', data));
});

req1.on('error', (err) => console.error('Error 1:', err.message));
req1.end();

setTimeout(() => {
  console.log('\nTesting connectivity to https://httpstat.us/200');

  const req2 = https.request('https://httpstat.us/200', (res) => {
    console.log('Status Code 2:', res.statusCode);
    let data = '';
    res.on('data', (chunk) => data += chunk);
    res.on('end', () => console.log('Response 2:', data));
  });

  req2.on('error', (err) => console.error('Error 2:', err.message));
  req2.on('timeout', () => console.error('Timeout 2: Connection timed out'));
  req2.setTimeout(5000);
  req2.end();
}, 1000);
"

